// Tạo thanh toán
async function createPayment(orderId, amount, returnUrl) {
  const { data } = await gateway.post('/transactions/pay', {
    orderId,
    amount,
    returnUrl,
    metadata: { source: 'website' },
  });
  return data.data;
}

